/**
 * Eukolia ambient declarations for the ported Overleaf tree.
 *
 * Two groups of modules have no type declarations in this project:
 *
 *  * the generated Lezer grammars, whose `.mjs` files are produced by
 *    `scripts/generate-grammars.mjs` — declaration files with the same
 *    basename (`.d.mts`) sit next to them and are generated by the same script;
 *  * `lodash`, `pdfjs-dist` and `mathjax`, which Overleaf declares through
 *    DefinitelyTyped or its own bundled types. Installing `@types/*` packages
 *    is outside this port's scope, so the exact surface the ported code uses is
 *    declared here.
 */

declare module 'lodash' {
  /* eslint-disable @typescript-eslint/no-explicit-any */
  export function debounce<T extends (...args: any[]) => any>(
    fn: T,
    wait?: number,
    options?: { leading?: boolean; trailing?: boolean; maxWait?: number }
  ): any

  export type DebouncedFunc<T extends (...args: never[]) => unknown> = T & {
    cancel(): void
    flush(): void
  }

  export function throttle<T extends (...args: any[]) => any>(
    fn: T,
    wait?: number,
    options?: { leading?: boolean; trailing?: boolean }
  ): any

  export function isEqual(a: unknown, b: unknown): boolean
  export function round(n: number, precision?: number): number
}

declare module 'pdfjs-dist/types/src/display/api' {
  export interface PDFPageViewport {
    width: number
    height: number
    scale: number
  }

  export interface PDFRenderTask {
    promise: Promise<void>
    cancel(): void
  }

  export interface PDFPageProxy {
    getViewport(params: { scale: number }): PDFPageViewport
    render(params: {
      canvasContext: CanvasRenderingContext2D
      viewport: PDFPageViewport
    }): PDFRenderTask
  }

  export interface PDFDocumentLoadingTask {
    promise: Promise<PDFDocumentProxy>
    destroy(): Promise<void>
  }

  export interface PDFDocumentProxy {
    numPages: number
    getPage(pageNumber: number): Promise<PDFPageProxy>
    destroy(): Promise<void>
  }
}

declare module 'mathjax' {
  /** Node entry point of the `mathjax` package (v4). */
  export function init(config?: Record<string, unknown>): Promise<{
    version: string
    startup: {
      promise: Promise<void>
      adaptor: {
        outerHTML(node: unknown): string
        innerHTML(node: unknown): string
        textContent(node: unknown): string
      }
      document: Record<string, unknown>
    }
    tex2svg(tex: string, options?: Record<string, unknown>): unknown
    tex2svgPromise(
      tex: string,
      options?: Record<string, unknown>
    ): Promise<unknown>
    tex2mmlPromise(tex: string, options?: Record<string, unknown>): Promise<string>
    texReset(labels?: number[]): void
    getMetricsFor(element: unknown, display?: boolean): Record<string, number>
    svgStylesheet(): unknown
    _: Record<string, unknown>
  }>
}
